#!/usr/bin/env bash
set -euo pipefail
umask 077
readonly ROOT=/var/lib/orloom/c3-suite-memory-20261013
readonly INCOMING=$ROOT.incoming
readonly OLD_NODE=/var/lib/orloom/c3-suite-proof-20261013/staging/node NODE_SHA=d1de76d8edf2fededf6f8b30d244e2c0529ac607923a018283b77e9c74bd932c
[[ ${EUID:-$(id -u)} -eq 0 && $# -eq 0 ]] || { echo 'usage: root stage-acceptance.sh' >&2; exit 64; }
[[ -d "$ROOT" && ! -L "$ROOT" && -d "$INCOMING" && ! -L "$INCOMING" && ! -e "$ROOT/source" && ! -L "$ROOT/source" && ! -e "$ROOT/source.git" && ! -L "$ROOT/source.git" && ! -e "$ROOT/runtime-files" && ! -L "$ROOT/runtime-files" ]] || { echo 'acceptance root is not safely prepared for first staging' >&2; exit 73; }
[[ -f "$OLD_NODE" && ! -L "$OLD_NODE" && $(sha256sum "$OLD_NODE" | cut -d' ' -f1) == "$NODE_SHA" ]] || { echo 'trusted pinned Node is unavailable' >&2; exit 69; }
for f in candidate.bundle candidate-identity.json stage-bindings.json runtime-acceptance.mjs cgroup-observer.mjs runtime-acceptance-entry.mjs runtime-snapshot-export.mjs export-acceptance-snapshot.sh prepare-acceptance-fixtures.mjs; do [[ -f "$INCOMING/$f" && ! -L "$INCOMING/$f" ]] || { echo "missing incoming $f" >&2; exit 66; }; done
[[ -d "$INCOMING/runtime-files" && ! -L "$INCOMING/runtime-files" && -f "$INCOMING/runtime-files/runtime-files.sha256" && ! -L "$INCOMING/runtime-files/runtime-files.sha256" && -f "$INCOMING/runtime-files/runtime-files-identity.json" && ! -L "$INCOMING/runtime-files/runtime-files-identity.json" ]] || { echo 'runtime payload is incomplete' >&2; exit 66; }
jq -e 'type=="object" and (keys|sort)==["approvedRef","baseSha","candidateSha","fixtureHelperSha256","observerHelperSha256","runtimeEntrySha256","runtimeHelperSha256","runtimePayloadSha256","runtimeSnapshotSha256","runtimeSnapshotShellSha256","sourceManifestSha256"] and (.baseSha|test("^[a-f0-9]{40}$")) and (.candidateSha|test("^[a-f0-9]{40}$")) and (.approvedRef|test("^refs/(heads|tags)/[A-Za-z0-9._/-]+$") and (contains("..")|not)) and (.sourceManifestSha256|test("^[a-f0-9]{64}$")) and (.runtimePayloadSha256|test("^[a-f0-9]{64}$")) and (.runtimeHelperSha256|test("^[a-f0-9]{64}$")) and (.observerHelperSha256|test("^[a-f0-9]{64}$")) and (.runtimeEntrySha256|test("^[a-f0-9]{64}$")) and (.runtimeSnapshotSha256|test("^[a-f0-9]{64}$")) and (.runtimeSnapshotShellSha256|test("^[a-f0-9]{64}$")) and (.fixtureHelperSha256|test("^[a-f0-9]{64}$"))' "$INCOMING/stage-bindings.json" >/dev/null
base=$(jq -r .baseSha "$INCOMING/stage-bindings.json"); candidate=$(jq -r .candidateSha "$INCOMING/stage-bindings.json"); ref=$(jq -r .approvedRef "$INCOMING/stage-bindings.json"); manifest=$(jq -r .sourceManifestSha256 "$INCOMING/stage-bindings.json"); payload=$(jq -r .runtimePayloadSha256 "$INCOMING/stage-bindings.json"); helper=$(jq -r .runtimeHelperSha256 "$INCOMING/stage-bindings.json"); observer=$(jq -r .observerHelperSha256 "$INCOMING/stage-bindings.json"); entry=$(jq -r .runtimeEntrySha256 "$INCOMING/stage-bindings.json"); snapshot=$(jq -r .runtimeSnapshotSha256 "$INCOMING/stage-bindings.json"); snapshot_shell=$(jq -r .runtimeSnapshotShellSha256 "$INCOMING/stage-bindings.json"); fixture_helper=$(jq -r .fixtureHelperSha256 "$INCOMING/stage-bindings.json")
[[ $(sha256sum "$INCOMING/runtime-files/runtime-files.sha256" | cut -d' ' -f1) == "$payload" && $(sha256sum "$INCOMING/runtime-acceptance.mjs" | cut -d' ' -f1) == "$helper" && $(sha256sum "$INCOMING/cgroup-observer.mjs" | cut -d' ' -f1) == "$observer" && $(sha256sum "$INCOMING/runtime-acceptance-entry.mjs" | cut -d' ' -f1) == "$entry" && $(sha256sum "$INCOMING/runtime-snapshot-export.mjs" | cut -d' ' -f1) == "$snapshot" && $(sha256sum "$INCOMING/export-acceptance-snapshot.sh" | cut -d' ' -f1) == "$snapshot_shell" && $(sha256sum "$INCOMING/prepare-acceptance-fixtures.mjs" | cut -d' ' -f1) == "$fixture_helper" ]] || { echo 'incoming acceptance binding differs' >&2; exit 65; }
(cd "$INCOMING/runtime-files" && sha256sum --check runtime-files.sha256 >/dev/null)
[[ -z $(find -P "$INCOMING/runtime-files" -type l -print -quit) && -z $(find -P "$INCOMING/runtime-files" ! -type d ! -type f -print -quit) ]] || { echo 'runtime payload has unsafe entries' >&2; exit 65; }
expected=$( { awk '/^[a-f0-9]{64}  / {print substr($0,67)}' "$INCOMING/runtime-files/runtime-files.sha256"; printf '%s\n' runtime-files.sha256 runtime-files-identity.json; } | LC_ALL=C sort); actual=$(find -P "$INCOMING/runtime-files" -type f -printf '%P\n' | LC_ALL=C sort); [[ $actual == "$expected" ]] || { echo 'runtime payload inventory differs' >&2; exit 65; }
count=$(wc -l < "$INCOMING/runtime-files/runtime-files.sha256")
jq -e --arg candidate "$candidate" --arg manifest "$manifest" --arg payload "$payload" --argjson count "$count" 'type=="object" and (keys|sort)==["candidate","fileCount","format","payloadManifestSha256","sourceManifestSha256"] and .format=="orloom-c3-acceptance-runtime-v1" and .candidate==$candidate and .sourceManifestSha256==$manifest and .payloadManifestSha256==$payload and .fileCount==$count' "$INCOMING/runtime-files/runtime-files-identity.json" >/dev/null
bundle=$(sha256sum "$INCOMING/candidate.bundle" | cut -d' ' -f1)
jq -e --arg base "$base" --arg candidate "$candidate" --arg ref "$ref" --arg manifest "$manifest" --arg bundle "$bundle" --arg payload "$payload" '.format=="orl-c3-suite-acceptance-transfer-v1" and .baseSha==$base and .candidateSha==$candidate and .sourceRef==$ref and .suiteManifestSha256==$manifest and .bundleSha256==$bundle and .payloadManifestSha256==$payload' "$INCOMING/candidate-identity.json" >/dev/null
gitc(){ env -i PATH=/usr/bin:/bin HOME=/root GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null GIT_TERMINAL_PROMPT=0 git "$@"; }
gitc clone --bare --no-local "$INCOMING/candidate.bundle" "$ROOT/source.git" >/dev/null
gitc --git-dir="$ROOT/source.git" rev-parse "$ref^{commit}" | grep -Fx "$candidate" >/dev/null; gitc --git-dir="$ROOT/source.git" merge-base --is-ancestor "$base" "$candidate"
[[ ! -e "$ROOT/source.git/objects/info/alternates" && ! -e "$ROOT/source.git/shallow" ]] || { echo 'bundle store is incomplete' >&2; exit 65; }
gitc clone --no-checkout "$ROOT/source.git" "$ROOT/source" >/dev/null; gitc -C "$ROOT/source" checkout --detach "$candidate" >/dev/null
[[ -z $(gitc -C "$ROOT/source" status --porcelain=v1) && $(sha256sum "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256" | cut -d' ' -f1) == "$manifest" ]] || { echo 'materialized source identity differs' >&2; exit 65; }
while IFS= read -r row; do [[ $row =~ ^([a-f0-9]{64})\ \ (.+)$ ]] || exit 65; hash=${BASH_REMATCH[1]}; rel=${BASH_REMATCH[2]}; [[ $rel != /* && $rel != *'..'* && -f "$ROOT/source/$rel" && ! -L "$ROOT/source/$rel" && $(sha256sum "$ROOT/source/$rel" | cut -d' ' -f1) == "$hash" ]] || { echo "source manifest mismatch: $rel" >&2; exit 65; }; done < "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256"
install -m 0500 "$OLD_NODE" "$ROOT/staging/node"; cp -a --no-preserve=ownership "$INCOMING/runtime-files" "$ROOT/runtime-files"; install -m 0400 "$INCOMING/runtime-acceptance.mjs" "$ROOT/runtime-acceptance.mjs"; install -m 0400 "$INCOMING/cgroup-observer.mjs" "$ROOT/cgroup-observer.mjs"; install -m 0400 "$INCOMING/runtime-acceptance-entry.mjs" "$ROOT/runtime-acceptance-entry.mjs"; install -m 0400 "$INCOMING/runtime-snapshot-export.mjs" "$ROOT/runtime-snapshot-export.mjs"; install -m 0500 "$INCOMING/export-acceptance-snapshot.sh" "$ROOT/export-acceptance-snapshot.sh"; install -m 0400 "$INCOMING/prepare-acceptance-fixtures.mjs" "$ROOT/prepare-acceptance-fixtures.mjs"; install -m 0400 "$INCOMING/stage-bindings.json" "$ROOT/stage-bindings.json"
[[ $(sha256sum "$ROOT/staging/node" | cut -d' ' -f1) == "$NODE_SHA" && $(sha256sum "$ROOT/runtime-files/runtime-files.sha256" | cut -d' ' -f1) == "$payload" && $(sha256sum "$ROOT/runtime-acceptance.mjs" | cut -d' ' -f1) == "$helper" && $(sha256sum "$ROOT/cgroup-observer.mjs" | cut -d' ' -f1) == "$observer" && $(sha256sum "$ROOT/runtime-snapshot-export.mjs" | cut -d' ' -f1) == "$snapshot" && $(sha256sum "$ROOT/export-acceptance-snapshot.sh" | cut -d' ' -f1) == "$snapshot_shell" ]] && (cd "$ROOT/runtime-files" && sha256sum --check runtime-files.sha256 >/dev/null) || { echo 'staged payload rehash failed' >&2; exit 65; }
[[ $(sha256sum "$ROOT/prepare-acceptance-fixtures.mjs" | cut -d' ' -f1) == "$fixture_helper" ]] || { echo 'fixture helper copy differs' >&2; exit 65; }
# A detached clone has only the origin branch; create the exact local reference once.
if gitc -C "$ROOT/source" show-ref --verify --quiet "$ref"; then echo "local source ref unexpectedly exists" >&2; exit 75; fi
gitc -C "$ROOT/source" update-ref "$ref" "$candidate" 0000000000000000000000000000000000000000
env -i PATH=/usr/bin:/bin HOME=/root ORLOOM_ACCEPTANCE_SOURCE_REPO="$ROOT/source" ORLOOM_ACCEPTANCE_CANDIDATE_SHA="$candidate" ORLOOM_ACCEPTANCE_BASE_SHA="$base" ORLOOM_ACCEPTANCE_SOURCE_REF="$ref" ORLOOM_ACCEPTANCE_FIXTURE_ROOT="$ROOT/fixtures" "$ROOT/staging/node" "$ROOT/prepare-acceptance-fixtures.mjs" >/dev/null
[[ -d "$ROOT/fixtures/objects.git" && ! -L "$ROOT/fixtures/objects.git" && -f "$ROOT/fixtures/fixtures.json" && ! -L "$ROOT/fixtures/fixtures.json" ]] || { echo 'controlled fixture preparation failed' >&2; exit 65; }
printf 'stage=PASS\ncandidate=%s\nbase=%s\nref=%s\nsource_manifest=%s\nsource_manifest_entries=%s\npayload=%s\nnode=%s\n' "$candidate" "$base" "$ref" "$manifest" "$(wc -l < "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256")" "$payload" "$NODE_SHA" > "$ROOT/staging/identity.txt"; chmod 0400 "$ROOT/staging/identity.txt"
